function mxLabel(root){(root||document).querySelectorAll('.mx table').forEach(t=>{if(t.dataset.lab)return;const hs=[...t.querySelectorAll('thead th')].map(th=>th.textContent.trim());if(!hs.length)return;t.dataset.lab=1;t.classList.add('mx-cards');t.querySelectorAll('tbody tr').forEach(tr=>[...tr.children].forEach((td,i)=>{if(hs[i]&&!td.dataset.l)td.dataset.l=hs[i]}))})}
let vxDq=0;new MutationObserver(()=>{if(document.querySelector('.mx table:not([data-lab])'))mxLabel();if(!vxDq&&typeof vxDecorate==='function'){vxDq=1;requestAnimationFrame(()=>{vxDq=0;try{vxDecorate()}catch(_){}})}}).observe(document.documentElement,{childList:true,subtree:true});
