const IBASE={hi:0x0900,mr:0x0900,bn:0x0980,pa:0x0A00,gu:0x0A80,or:0x0B00,ta:0x0B80,te:0x0C00,kn:0x0C80,ml:0x0D00};
const NORTH={hi:1,mr:1,bn:1,pa:1,gu:1,or:1};
const TCONS=[['ksh',[0x15,0x37]],['chh',[0x1B]],['sh',[0x36]],['ch',[0x1A]],['th',[0x24]],['dh',[0x27]],['bh',[0x2D]],['gh',[0x18]],['kh',[0x16]],['ph',[0x2B]],['zh',[0x34]],['jh',[0x1D]],['x',[0x15,0x38]],['k',[0x15]],['g',[0x17]],['c',[0x15]],['q',[0x15]],['j',[0x1C]],['z',[0x1C]],['t',[0x1F]],['d',[0x26]],['n',[0x28]],['p',[0x2A]],['f',[0x2B]],['b',[0x2C]],['m',[0x2E]],['y',[0x2F]],['r',[0x30]],['l',[0x32]],['v',[0x35]],['w',[0x35]],['s',[0x38]],['h',[0x39]]];
